function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

function getFileInfo(mediaClient, fileNode, warnings) {
  if (!fileNode) {
    return null;
  }

  let originalSourceUrl;
  let filename;
  let mimeType;

  if (fileNode.__typename === 'MediaImage') {
    originalSourceUrl = fileNode.image?.url || fileNode.imageOriginalSource?.url;
    filename = fileNode.filename;
    mimeType = fileNode.mimeType;
  } else if (fileNode.__typename === 'Video') {
    originalSourceUrl = fileNode.videoOriginalSource?.url;
    filename = fileNode.filename;
    mimeType = fileNode.videoOriginalSource?.mimeType;
  } else if (fileNode.__typename === 'GenericFile') {
    originalSourceUrl = fileNode.url;
    filename = fileNode.filename;
    mimeType = fileNode.mimeType;
  } else {
    warnings.push(`Unsupported file type: ${fileNode.__typename} with ID ${fileNode.id}`);
    return null;
  }

  if (!originalSourceUrl && !filename) {
    warnings.push(`Skipping file ${fileNode.id} due to missing source URL or filename`);
    return null;
  }

  if (!filename && originalSourceUrl) {
    filename = mediaClient.extractFilenameFromUrl(originalSourceUrl);
  }

  if (!filename) {
    warnings.push(`Could not determine filename for file ${fileNode.id}`);
    return null;
  }

  const normalizedFilename = mediaClient.normalizeFilename(filename) || filename;
  const extension = normalizedFilename.includes('.')
    ? normalizedFilename.split('.').pop().toLowerCase()
    : '';
  const baseName = extension
    ? normalizedFilename.slice(0, -(extension.length + 1))
    : normalizedFilename;

  return {
    id: fileNode.id,
    typename: fileNode.__typename,
    alt: fileNode.alt,
    originalSourceUrl,
    filename: normalizedFilename,
    baseName,
    extension,
    mimeType
  };
}

async function syncMedia({ config, client }) {
  const result = makeResult();
  const sourceFiles = await client.source.media.listAll();
  const destinationFiles = await client.destination.media.listAll();

  for (const sourceFileNode of sourceFiles) {
    const sourceFile = getFileInfo(client.source.media, sourceFileNode, result.warnings);
    if (!sourceFile) {
      continue;
    }

    const destinationFileNode = destinationFiles.find((candidate) => {
      const candidateInfo = getFileInfo(
        client.destination.media,
        candidate,
        result.warnings
      );
      return (
        candidateInfo &&
        sourceFile.baseName === candidateInfo.baseName &&
        sourceFile.extension === candidateInfo.extension
      );
    });

    const destinationFile = getFileInfo(
      client.destination.media,
      destinationFileNode,
      result.warnings
    );

    if (!destinationFile) {
      if (config.updateOnly) {
        continue;
      }

      let contentType = 'IMAGE';
      if (sourceFile.typename === 'Video') {
        contentType = 'VIDEO';
      } else if (sourceFile.typename === 'GenericFile') {
        contentType = 'FILE';
      }

      try {
        await client.destination.media.create({
          alt: sourceFile.alt,
          contentType,
          originalSource: sourceFile.originalSourceUrl,
          filename: sourceFile.filename
        });
        result.created += 1;
      } catch (error) {
        result.errors.push(`Error creating file ${sourceFile.filename}: ${error.message}`);
      }

      continue;
    }

    if (sourceFile.alt !== destinationFile.alt && !config.createOnly) {
      try {
        await client.destination.media.update({
          id: destinationFile.id,
          alt: sourceFile.alt
        });
        result.updated += 1;
      } catch (error) {
        result.errors.push(`Error updating file ${destinationFile.filename}: ${error.message}`);
      }
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    for (const destinationFileNode of destinationFiles) {
      const destinationFile = getFileInfo(
        client.destination.media,
        destinationFileNode,
        result.warnings
      );

      if (!destinationFile) {
        continue;
      }

      const sourceFileExists = sourceFiles.some((sourceNode) => {
        const sourceFile = getFileInfo(client.source.media, sourceNode, result.warnings);
        return (
          sourceFile &&
          sourceFile.baseName === destinationFile.baseName &&
          sourceFile.extension === destinationFile.extension
        );
      });

      if (sourceFileExists) {
        continue;
      }

      try {
        await client.destination.media.delete(destinationFile.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(
          `Error deleting file "${destinationFile.filename}": ${error.message}`
        );
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceFiles.length,
    destinationCount: destinationFiles.length
  };

  return result;
}

module.exports = {
  syncMedia,
  getFileInfo
};
